#!/usr/bin/env python3
"""Build the MHGC static multi-page website from content/site-content.json.
Run: python scripts/build.py
All URLs have physical index.html routes; no server rewrite is required.
"""
import os,json,html,textwrap,re
from pathlib import Path
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'content/site-content.json').read_text())
ROUTES=['','about','about/organizer','about/organizing-committee','about/supporting-organizations', 'about/supporting-organizations/mission','about/supporting-organizations/sports-department','about/supporting-organizations/bssa','about/supporting-organizations/kreeda-bharati','about/supporting-organizations/hockey-india','about/supporting-organizations/hab','about/supporting-organizations/bsacs', '2027','2027/venue','2027/teams','2027/register','2027/accommodation-food','2026','2026/results','2026/gallery','2026/videos','2026/press','sponsorship','sponsorship/deliverables','sponsorship/past-sponsors','contact','privacy']+['2026/gallery/'+x['slug'] for x in D['albums']]
current=''
def pref(): return '../'*len([x for x in current.split('/') if x])
def url(route=''): return pref() + (route.strip('/')+'/' if route else '') + 'index.html'
def a(route,txt,cls='',other=''): return f'<a href="{url(route)}"'+(f' class="{cls}"' if cls else '')+((' '+other) if other else '')+f'>{txt}</a>'
def img(file,alt='',cls='',extra=''): return f'<img src="{pref()}{file}" alt="{html.escape(alt,quote=True)}"'+(f' class="{cls}"' if cls else '')+(f' {extra}' if extra else '')+' loading="lazy">'
def button(route,txt,kind='blue'): return a(route,txt+' <span aria-hidden="true">↗</span>',f'button {kind}')
def title(t,sub=None,kicker='THE STORY',link=None):
 return f'<div class="section-heading"><div><div class="eyebrow">{kicker}</div><h2>{t}</h2>'+ (f'<p>{sub}</p>' if sub else '') + '</div>'+(f'<div class="right">{a(link,"Discover more <span aria-hidden=true>→</span>","link-arrow")}</div>' if link else '')+'</div>'
def section(children,mode='',id=''): return f'<section class="section {mode}"'+(f' id="{id}"' if id else '')+f'><div class="container">{children}</div></section>'
def chip(txt):return f'<span class="chip">{txt}</span>'
def hero(page_title,excerpt,tag='OFFICIAL EVENT WEBSITE',buttons='',crumb=True):
 return f'''<header class="page-hero"><div class="container">{f'<div class="breadcrumb">{a("","HOME")} / {html.escape(page_title)}</div>' if crumb else ''}<div class="eyebrow light" style="margin-top:18px">{tag}</div><h1>{page_title}</h1><p>{excerpt}</p>{f'<div class="hero-actions">{buttons}</div>' if buttons else ''}</div></header>'''
def infocard(h,p,num='01'):return f'<article class="detail-card"><div class="num">{num}</div><h3>{h}</h3><p>{p}</p></article>'
def media_empty(title='This archive is being prepared',description='Official material will appear here when it is supplied and cleared for publishing.'):
 return f'<div class="empty-media"><div class="empty-symbol" aria-hidden="true">⌑</div><h3>{title}</h3><p>{description}</p>{a("contact","Request an archive update →","link-arrow")}</div>'
def albumcard(al,i):
 cover=(img(al['photos'][0]['thumbnail'],al['name'],'album-cover') if al['photos'] else '')
 return a('2026/gallery/'+al['slug'],f'<div class="album-art">{cover}<span>{i:02d}</span></div><div class="album-meta"><h3>{al["name"]}</h3><p>{al["description"]}</p><small>{len(al["photos"])} archive photographs &nbsp; ↗</small></div>','album-card')

def gallerytile(al,i):
 cover=img(al['photos'][0]['thumbnail'],al['name']+' album image','gallery-cover') if al['photos'] else ''
 return a('2026/gallery/'+al['slug'],f'{cover}<div class="photo-id">ARCHIVE {i:02d}</div><h3>{al["name"]}</h3><small>{len(al["photos"])} photos · View album ↗</small>','gallery-tile')

def reels(area='home'):
 return f'''<div class="flex space-between" style="margin-bottom:18px"><span class="small-note">Real tournament footage and selected public Instagram posts. Tap any clip to watch.</span><div class="scroller-controls"><button class="round-control" data-scroll-reels="prev" aria-label="Scroll reels left">‹</button><button class="round-control" data-scroll-reels="next" aria-label="Scroll reels right">›</button></div></div><div class="reel-scroller" data-reel-scroller data-reel-area="{area}"></div>'''

def plain_notice():return '<p class="small-note">2027 participation figures, partners, registration timelines and final award amounts remain subject to organizer confirmation.</p>'

NAV=[('Home','',''),('About','about',[('Mahamana Hockey Gold Cup','about'),('Organizer','about/organizer'),('Organizing Committee','about/organizing-committee'),('Supporting Organizations','about/supporting-organizations')]),('MMHGC 2027','2027',[('About, Dates & Venue','2027'),('Participating Teams','2027/teams'),('Registration Form','2027/register'),('Accommodation & Food','2027/accommodation-food'),('Venue & Directions','2027/venue')]),('CENTER','',''),('MMHGC 2026','2026',''),('Sponsorship','sponsorship',[('Sponsorship Opportunities','sponsorship'),('Deliverables','sponsorship/deliverables'),('Past Sponsors','sponsorship/past-sponsors')]),('Contacts','contact','')]
def navigation():
 ds=''
 for n,route,dropdown in NAV:
  if n=='CENTER': ds+=f'<div class="nav-item logo-slot">{a("",img("assets/brand/mhgc-2027-logo.png","Mahamana Hockey Gold Cup 2027 logo"),"brand-center","aria-label=\"Go home\"")}</div>';continue
  active=current==route or (route and current.startswith(route+'/'))
  if dropdown:
   items=''.join(a(r,label,other=('aria-current="page"' if current==r else '')) for label,r in dropdown)
   if n=='About':
    items+='<div class="group-label">INSTITUTIONAL PROFILES</div>'+''.join(a('about/supporting-organizations/'+k,v) for k,v in [('mission','Mahamana Malviya Mission'),('sports-department','Bihar Sports Department'),('bssa','Bihar State Sports Authority'),('kreeda-bharati','Kreeda Bharati'),('hockey-india','Hockey India'),('hab','Hockey Association of Bihar'),('bsacs','Bihar State AIDS Control Society')])
   ds+=f'<div class="nav-item dropdown-wrap {"active" if active else ""}"><button class="nav-trigger" aria-expanded="false" aria-haspopup="true">{n}<span class="chevron">▾</span></button><div class="nav-dropdown">{items}</div></div>'
  else: ds+=f'<div class="nav-item {"active" if active else ""}">{a(route,n,"nav-link",("aria-current=\"page\"" if current==route else ""))}</div>'
 mobile=''
 for n,route,dropdown in NAV:
  if n=='CENTER':continue
  if dropdown:
   items=''.join(a(r,label) for label,r in dropdown)
   if n=='About': items+=''.join(a('about/supporting-organizations/'+k,v) for k,v in [('mission','Mahamana Malviya Mission'),('sports-department','Department of Sports'),('bssa','BSSA'),('kreeda-bharati','Kreeda Bharati'),('hockey-india','Hockey India'),('hab','HAB'),('bsacs','BSACS')])
   mobile+=f'<div class="mobile-group"><button type="button" aria-expanded="false">{n}<span>+</span></button><div class="mobile-links">{items}</div></div>'
  else:mobile+=a(route,n)
 return f'''<div class="topbar"><div class="container"><div><strong>MAHAMANA HOCKEY GOLD CUP 2027</strong> &nbsp;·&nbsp; 15–17 JANUARY &nbsp;·&nbsp; RAJGIR, BIHAR</div><div class="right-top">UNDER-16 &nbsp; | &nbsp; BOYS &amp; GIRLS</div></div></div><nav class="header" aria-label="Main navigation"><div class="desktop-nav">{ds}</div><div class="mobile-head">{a('',img('assets/brand/mhgc-2027-logo.png','2027 tournament logo')+' <span>MAHAMANA HOCKEY<br>GOLD CUP 2027</span>','mobile-logo')}<button class="hamburger" aria-label="Open navigation" aria-controls="mobile-panel" aria-expanded="false">☰</button></div><div class="mobile-panel" id="mobile-panel">{mobile}</div></nav>'''
def foot():
 nav1=[('About the Cup','about'),('The Organizer','about/organizer'),('Organizing Committee','about/organizing-committee'),('Institutional Profiles','about/supporting-organizations')]
 nav2=[('2027 Event Overview','2027'),('Venue & Directions','2027/venue'),('Participating Teams','2027/teams'),('Registration','2027/register')]
 nav3=[('2026 Highlights','2026'),('Results & Champions','2026/results'),('Photo Galleries','2026/gallery'),('Video & Reels','2026/videos'),('Press Archive','2026/press')]
 def fcol(h,arr):return f'<div><h4>{h}</h4>'+''.join(a(r,t) for t,r in arr)+'</div>'
 return f'''<section class="cta-band"><div class="container flex space-between" style="align-items:end;flex-wrap:wrap;gap:22px"><div><div class="eyebrow light">BE PART OF THE JOURNEY</div><h2>The next generation of hockey starts here.</h2><p style="margin-bottom:0">Discover emerging talent. Celebrate fair play. Support a bigger sporting future.</p></div><div class="flex" style="flex-wrap:wrap">{button('2027/register','Registration updates','gold')}{button('sponsorship','Become a partner','outline-light')}</div></div></section><footer class="footer"><div class="container"><div class="footer-top"><div><div class="footer-brand">{img('assets/brand/mhgc-2027-logo.png','MHGC shield')}<div><b>MAHAMANA<br>HOCKEY GOLD CUP</b><div class="eyebrow light" style="margin-top:6px">RAJGIR 2027</div></div></div><p style="margin:22px 0 10px">An Under-16 inter-state hockey initiative for boys and girls, organized by Mahamana Malviya Mission — Bihar Unit.</p><p style="color:#e4c47f;font-family:'Noto Sans Devanagari',sans-serif">{D['event']['tagline']}</p></div>{fcol('ABOUT',nav1)}{fcol('2027 EVENT',nav2)}{fcol('EXPLORE 2026',nav3)}</div><div class="footer-contact"><a href="mailto:mmmbiharunit@gmail.com">✉ mmmbiharunit@gmail.com</a><a href="tel:+919311549600">☎ +91 93115 49600</a><a href="tel:+918936040088">☎ +91 89360 40088</a><a href="tel:+917992362557">☎ +91 79923 62557</a></div><div class="footer-bottom"><span>© 2027 Mahamana Hockey Gold Cup · Organizer: Mahamana Malviya Mission — Bihar Unit.</span><span>{a('sponsorship','Sponsorship')} &nbsp; · &nbsp; {a('contact','Contact')} &nbsp; · &nbsp; {a('privacy','Privacy')}</span></div></div></footer>'''

# ---------------------------------- PAGES ----------------------------------
def home():
 logos=img('assets/brand/mission-bihar.png','Mahamana Malviya Mission Bihar Unit')+img('assets/brand/mission-national.png','Mahamana Malviya Mission national unit')+img('assets/brand/bssa.jpg','Bihar State Sports Authority historical 2026 supporter')+img('assets/brand/hab.jpg','Hockey Association of Bihar historical 2026 supporter')
 hero_home=f'''<section class="hero"><div class="container"><div class="hero-copy"><div class="eyebrow light">SECOND EDITION · UNDER-16 INTER-STATE HOCKEY</div><h1>WHERE YOUNG <em>CHAMPIONS</em> BEGIN.</h1><div class="hero-sub">Mahamana Hockey Gold Cup 2027</div><p>A bigger stage for young talent. A stronger future for hockey. Bringing boys and girls together to compete, grow and inspire the next generation.</p><div class="hero-pills"><div class="hero-pill"><span>THE DATES</span><strong>15–17 JANUARY 2027</strong></div><div class="hero-pill"><span>THE VENUE</span><strong>INTERNATIONAL HOCKEY STADIUM, RAJGIR</strong></div></div><div class="hero-buttons">{button('2027','Explore 2027','gold')}{button('2027/register','Registration updates','outline-light')}{button('2026/videos','Watch the highlights','outline-light')}</div></div><div class="hero-art"><div class="hero-ring"></div>{img('assets/brand/mhgc-2027-logo.png','Mahamana Hockey Gold Cup 2027 official shield','shield',extra='loading="eager"')}<div class="hero-small"><b>02 / 02</b> A new edition. One shared ambition: a bigger future for young players.</div></div></div></section>'''
 impact='''<div class="impact"><div class="container impact-grid"><div class="impact-label"><strong>OUR 2026 FOUNDATION</strong><span>Inaugural-edition figures.<br>Real results. A growing legacy.</span></div>'''+''.join(f'<div class="impact-number"><b>{n}</b><span>{txt}</span></div>' for n,txt in [('16','TEAMS'),('07','STATES'),('30','MATCHES'),('03','DAYS')])+'</div></div>'
 story=section('<div class="editorial-split"><div>'+title('A tournament with a purpose.','The Gold Cup gives talented young players, particularly those with fewer pathways to the spotlight, the chance to experience high-level inter-state competition.','OUR PURPOSE')+'<p>Inspired by the educational and social ideals of Mahamana Pandit Madan Mohan Malviya, the tournament links sporting opportunity with discipline, determination and teamwork. Its first chapter began in Rajgir in January 2026 — and the journey continues in 2027.</p><div style="margin-top:25px">'+button('about','Our story')+'</div></div><div class="poster-visual">'+img('assets/brand/golu-gauraiya.png','Golu Gauraiya official hockey mascot')+'<div class="corner-note">MEET THE SPIRIT OF THE GAME</div></div></div>')
 missions=[('01','Spot hidden talent','Create opportunities for promising young players whose talent deserves wider recognition.'),('02','Build Bihar’s pathways','Encourage exposure, confidence and competitive experience for players from Bihar.'),('03','Celebrate equal opportunity','Recognise both the boys’ and girls’ categories with equal competitive respect.'),('04','Compete on a major stage','Offer young athletes the opportunity to play at the International Hockey Stadium, Rajgir.')]
 mission=section(title('More than a championship.','A youth-focused initiative where sport becomes a doorway to confidence, character and opportunity.','THE FOUR PILLARS')+'<div class="grid cols4">'+''.join(f'<article class="card mission-card"><div class="mission-icon">{n}</div><h3>{h}</h3><p class="muted">{p}</p></article>' for n,h,p in missions)+'</div>','soft')
 video=section(title('Watch the game. Feel the energy.','Play original tournament video clips directly, then explore public Instagram reels in the on-site popup viewer.','THE VIDEO EXPERIENCE','2026/videos')+reels(),'','reel-home')
 results=section(title('Glory from 2026.','A first edition that brought teams from seven states to Rajgir and celebrated both boys’ and girls’ hockey.','CHAMPIONS OF THE FIRST EDITION','2026/results')+'<div class="grid cols2">'+result_card('BOYS’ CHAMPIONSHIP','UTTAR PRADESH','Jharkhand','BSSA Bihar (Rajgir)')+result_card('GIRLS’ CHAMPIONSHIP','JHARKHAND (SIMDEGA)','Uttar Pradesh (Gorakhpur)','BSSA Bihar (Rajgir)')+'</div>','soft')
 gallery=section(title('Moments that matter.','See original moments captured at the 2026 Gold Cup: stage, trophies, champions, guests and celebrations.','2026 PHOTO ARCHIVE','2026/gallery')+'<div class="gallery-preview">'+''.join(gallerytile(x,i) for i,x in enumerate([a for a in D['albums'] if a['photos']][:5],1))+'</div><div style="margin-top:28px;text-align:center">'+button('2026/gallery','View complete 2026 gallery','blue')+'</div>')
 photo_feature=section(title('Real memories. Real champions.','A glimpse of original photographs from the first Gold Cup in Rajgir.','FROM THE 2026 ARCHIVE')+'<div class="champion-photos">'+''.join('<a class="champion-photo" href="'+url('2026/gallery')+'">'+img('assets/photos/'+f,'2026 '+label)+'<span>'+label+' ↗</span></a>' for f,label in [('event-03-thumb.webp','Boys’ Champions · Uttar Pradesh'),('event-10-thumb.webp','Girls’ Champions · Jharkhand (Simdega)'),('event-02-thumb.webp','The inaugural event · Rajgir')])+'</div>')
 mascot=section('<div class="mascot-band"><div class="mascot-text"><div class="eyebrow">MEET THE OFFICIAL MASCOT</div><h2>Small wings.<br>Big dreams.</h2><p>Golu “Gauraiya” is the spirited sparrow who embodies quick thinking, tireless energy and the courage of aspiring champions.</p><div class="devanagari">“'+D['event']['tagline']+'”</div>'+a('about','Read the Gold Cup story →','link-arrow')+'</div>'+img('assets/brand/golu-gauraiya.png','Official mascot Golu Gauraiya')+'</div>')
 venue=section('<div class="editorial-split"><div class="venue-panel"><div class="rink"></div><div class="venue-copy"><div class="eyebrow light">THE LOCATION</div><h2 style="margin:15px 0 16px">RAJGIR,<br>BIHAR.</h2><p style="color:#d7e6f4">International Hockey Stadium — the stage for the 2027 tournament.</p><div style="margin-top:90px">'+a('2027/venue','Explore venue & directions →','link-arrow light')+'</div></div></div><div>'+title('Where the next chapter unfolds.','A destination with a distinctive setting, hosting talented Under-16 teams for the second edition of the Gold Cup.','VENUE SPOTLIGHT')+'<p>The setting is more than a backdrop. Competing in a dedicated international hockey venue is an opportunity to experience the standards, atmosphere and ambition that make a tournament memorable.</p>'+button('2027/venue','Venue & directions')+'</div></div>','soft')
 sponsors=section('<div class="grid cols2" style="align-items:center"><div>'+title('Join the team behind the teams.','From athlete support to event hospitality and visibility, sponsorship helps extend the tournament’s reach and opportunity.','CORPORATE PARTNERSHIPS')+'<p>Our 2027 sponsorship proposals offer different ways for responsible brands and institutions to participate. Proposed placements and benefits are subject to the final agreement and venue approvals.</p>'+button('sponsorship','Explore partnership tiers','gold')+'</div><div class="card" style="padding:34px;background:#f9fbff"><div class="eyebrow">PAST EDITION SUPPORT REFERENCES</div><div class="partner-line">'+logos+'</div><p class="small-note" style="margin-top:20px">Institutional logos shown in their historical 2026 support context, not as confirmed 2027 sponsorships.</p></div></div>')
 return hero_home+impact+story+mission+video+results+photo_feature+gallery+mascot+venue+sponsors

def result_card(cat,champ,runner,third):return f'<article class="results-panel"><span class="badge amber">{cat}</span><div class="eyebrow" style="margin-top:25px">2026 CHAMPIONS</div><div class="winner">{champ}</div><div class="lineitem"><span>Runner-up</span><b>{runner}</b></div><div class="lineitem"><span>Third place</span><b>{third}</b></div>{a("2026/results","View complete result →","link-arrow")}</article>'

def about():
 lead='The Mahamana Hockey Gold Cup is an Under-16 inter-state hockey competition for boys and girls. It seeks to discover promising talent, build sporting confidence and bring competitive experience within reach of young athletes — with a special focus on Bihar.'
 x=hero('About the Gold Cup',lead,'OUR VISION · OUR STORY',button('2027','2027 edition','gold'))
 x+=section('<div class="editorial-split"><div>'+title('A wider stage for a younger generation.','Excellence grows when opportunity meets preparation.','WHY THE GOLD CUP')+'<p>While talent can flourish in every city, town or village, exposure and competitive opportunities are not always evenly available. This tournament is designed to create an encouraging bridge between emerging athletes and high-level inter-state hockey.</p><p>It is inspired by Mahamana Pandit Madan Mohan Malviya’s holistic approach to education: development of the mind and character alongside physical strength and public purpose.</p></div><div class="poster-visual">'+img('assets/brand/mhgc-2027-logo.png','Mahamana 2027 official logo')+'</div></div>')
 x+=section(title('Our commitments.','A stronger hockey culture depends on players, families, institutions and opportunities working together.','THE MISSION')+'<div class="grid cols2">'+''.join(infocard(h,p,f'{i:02d}') for i,(h,p) in enumerate([('Talent identification','Make room for gifted Under-16 players to demonstrate skills against capable peers.'),('Opportunity for Bihar','Help young players from Bihar build confidence through meaningful competitive exposure.'),('Girls and boys together','Give both categories recognition and a platform in the same sporting celebration.'),('Discipline and sportsmanship','Develop respect, resilience, teamwork and healthy competition.'),('Quality sporting environment','Create a positive experience around the international hockey venue in Rajgir.'),('Long-term inspiration','Encourage schools, communities and families to take a greater interest in hockey.')],1))+'</div>','soft')
 x+=section(title('Two chapters. One continuing purpose.','The inaugural edition established the platform. The upcoming edition moves the journey forward.','OUR JOURNEY')+'<div class="grid cols2">'+infocard('19–21 January 2026','The first Mahamana Hockey Gold Cup brought 16 teams from seven states to Rajgir for 30 matches.','2026')+infocard('15–17 January 2027','The second edition is scheduled at the International Hockey Stadium, Rajgir, with the same commitment to nurturing young athletes.','2027')+'</div><div style="margin-top:24px">'+button('about/organizer','Meet the organizer')+'</div>')
 return x

def organizer():
 x=hero('The Organizer','Mahamana Malviya Mission — Bihar Unit is the organizing body behind Mahamana Hockey Gold Cup, bringing an education-inspired commitment to youth development into the field of sport.','MAHAMANA MALVIYA MISSION · BIHAR UNIT')
 x+=section('<div class="editorial-split"><div>'+title('From the ideals of education to the energy of sport.','A youth development initiative inspired by Mahamana Pandit Madan Mohan Malviya.','THE ORGANIZATION')+'<p>The Bihar Unit of Mahamana Malviya Mission, associated with the wider mission network and Banaras Hindu University alumni, undertakes the tournament to foster opportunity, character-building and an active sporting culture.</p><p>The inspiration is simple: development is most meaningful when academic aspiration, social responsibility, discipline and physical activity reinforce one another.</p><p>Through the Gold Cup, that thinking takes a tangible form — a competitive platform for boys and girls who may one day represent their districts, states and country.</p></div><div class="grid cols2" style="align-items:center;gap:20px"><div class="card" style="text-align:center">'+img('assets/brand/mission-bihar.png','Mahamana Malviya Mission Bihar Unit',extra='style="height:170px;object-fit:contain"')+'<p class="small-note">Organizing body: Bihar Unit</p></div><div class="card" style="text-align:center">'+img('assets/brand/mission-national.png','Mahamana Malviya Mission national logo',extra='style="height:170px;object-fit:contain"')+'<p class="small-note">National mission network</p></div></div></div>')
 x+=section(title('Why organize a hockey tournament?','Because aspiration needs both inspiration and access.','PUBLIC PURPOSE')+'<div class="grid cols3">'+infocard('Real sporting exposure','Young players need quality competition as much as they need practice.','01')+infocard('Community pride','Hockey creates shared sporting moments for schools, families and local communities.','02')+infocard('Character through competition','The experience strengthens confidence, resilience and respect for others.','03')+'</div>','soft')
 x+=section('<div class="info-strip"><h3>Historical organizing reference</h3><p>Organizing Secretariat for the 2026 edition: Hari Nagar Township, Near AIIMS, Patna, Bihar. Public 2027 correspondence details should be reconfirmed by the organizers before launch.</p>'+button('contact','Contact page')+'</div>')
 return x

def committee():
 return hero('Organizing Committee','The 2027 committee, distinguished guests and office-bearers will be announced by the organizers once the final roster has been verified.','2027 TEAM · ANNOUNCEMENT PENDING')+section(media_empty('2027 organizing committee to be announced','The 2026 guest list and previous organizing committee are historical records, and are not presented as 2027 officials.')+'<div class="grid cols3" style="margin-top:30px">'+''.join(infocard(h,p,str(i).zfill(2)) for i,(h,p) in enumerate([('Leadership & coordination','Official committee members and responsibilities will be listed here.'),('Tournament operations','Event logistics, registrations and sporting coordination will be added after confirmation.'),('Media & communications','Press, digital and guest-relations contacts will be added when assigned.')],1))+'</div>')

ORG=[('mission','Mahamana Malviya Mission','The national mission network and the Bihar Unit share inspiration drawn from the educational and public-service ideals of Pandit Madan Mohan Malviya.','assets/brand/mission-national.png'),('sports-department','Department of Sports, Government of Bihar','The government sports ecosystem is an important institutional context for the development of sporting opportunity in Bihar.',None),('bssa','Bihar State Sports Authority (BSSA)','BSSA is referenced as a supporting institution for the 2026 Gold Cup and is central to the state’s sporting infrastructure.','assets/brand/bssa.jpg'),('kreeda-bharati','Kreeda Bharati','A sporting organization referenced among the supporters of the inaugural tournament.',None),('hockey-india','Hockey India','The national governing federation for field hockey in India, referenced in the Gold Cup’s supporting-organization brief.',None),('hab','Hockey Association of Bihar (HAB)','The state-level hockey association appeared among the supporting logos and institutions in the 2026 catalogue.','assets/brand/hab.jpg'),('bsacs','Bihar State AIDS Control Society (BSACS)','Referenced by the organizers among institutions associated with the 2026 event and its wider public engagement.',None)]
def org_card(t):
 slug,name,descr,logo=t
 visual=img(logo,name,extra='style="height:75px;max-width:145px;object-fit:contain"') if logo else f'<div style="height:75px;display:grid;place-items:center;font-size:15px;font-weight:800;color:var(--blue)">{name}</div>'
 return f'<article class="card">{visual}<h3 style="margin-top:18px">{name}</h3><p class="muted">{descr}</p>{a("about/supporting-organizations/"+slug,"Read institutional profile →","link-arrow")}</article>'
def organizations():return hero('Supporting Organizations','Institutions and sporting bodies mentioned in the historical event materials. Past association does not automatically imply a confirmed 2027 partnership.','INSTITUTIONAL CONTEXT · HISTORICAL REFERENCES')+section('<div class="info-strip gold-tint"><b>Important distinction:</b> The organizations below are referenced in supplied 2026 source materials. The confirmed 2027 partnership list has not yet been supplied.</div><div class="grid cols3" style="margin-top:29px">'+''.join(org_card(x) for x in ORG)+'</div>')
def orgdetail(slug):
 o=next(x for x in ORG if x[0]==slug)
 x=hero(o[1],o[2],'SUPPORTING ORGANIZATIONS · BACKGROUND PROFILE')
 x+=section('<div class="grid cols2" style="align-items:start;gap:55px"><div><h2>Institutional profile</h2><p>'+o[2]+'</p><p>The Mahamana Hockey Gold Cup acknowledges the wider sports and social-development ecosystem around youth sporting opportunities. This profile is a context page, not a statement of a new sponsorship or formal 2027 commitment.</p>'+button('about/supporting-organizations','All organizations')+'</div><div class="info-strip"><div class="eyebrow">PARTNERSHIP STATUS</div><h3 style="margin-top:15px">Historical reference</h3><p>Confirmation of active involvement in the 2027 edition will be published after written approval or an official announcement.</p></div></div>')
