def adultform(kind):
 if kind=='register':
  fields=[('organization','Team / academy / institution','text','Name of participating organization'),('representative','Adult representative’s name','text','Full name'),('category','Interested category','select',['Boys’ Under-16','Girls’ Under-16','Both categories']),('state','State / region','text','State'),('email','Representative email','email','name@example.com'),('phone','Representative phone','tel','Contact number')]
  subtitle='Adult team coordinators can share their interest. This is not official team entry or age verification. No personal data about children is requested.'
 elif kind=='sponsor':
  fields=[('organization','Company / organization','text','Organization name'),('representative','Contact person (adult)','text','Full name'),('category','Sponsorship interest','select',[t['name'] for t in D['sponsorTiers']]),('state','Cash or in-kind proposal','select',['Cash','In kind','Open to discussion']),('email','Business email','email','name@organization.com'),('phone','Contact phone','tel','Contact number')]
  subtitle='Tell our team how your business would like to support the next generation of hockey players.'
 else:
  fields=[('organization','Organization (optional)','text','Company, school or association'),('representative','Your name (adult)','text','Full name'),('category','Enquiry topic','select',['General enquiry','Team registration','Sponsorship','Media & press','Event photographs','Other']),('state','Location','text','City / state'),('email','Your email','email','name@example.com'),('phone','Phone number (optional)','tel','Contact number')]
  subtitle='Send a message to the Mahamana Hockey Gold Cup organizing team.'
 frm='<div class="form-grid">'
 for key,label,typ,p in fields:
  if typ=='select':control=f'<select name="{key}" required><option value="">Select an option</option>'+''.join(f'<option>{html.escape(x)}</option>' for x in p)+'</select>'
  else:control=f'<input name="{key}" type="{typ}" placeholder="{html.escape(p)}"'+(' required' if key in ['representative','email'] or (key=='organization' and kind!='contact') else '')+' autocomplete="on" maxlength="180">'
  control=control.replace(' name=',f' id="{kind}-{key}" name=',1)
  frm+=f'<div class="field"><label for="{kind}-{key}">{label}</label>{control}</div>' 
 frm+='<div class="field full"><label for="'+kind+'-message">Message / additional details</label><textarea name="message" id="'+kind+'-message" maxlength="1800" placeholder="Write your enquiry here..."></textarea></div><div class="hidden-trap" aria-hidden="true"><label>Website<input type="text" tabindex="-1" autocomplete="off" name="website_field"></label></div><label class="field full consent"><input type="checkbox" name="consent" value="yes" required> <span>I am an adult (18+) and consent to sharing these details with the organizer for responding to this enquiry. I understand this is not a confirmed team registration.</span></label></div>'
 return f'<div class="form-card"><div class="fake-status">SECURE GOOGLE SHEETS INTAKE · ACTIVATES AFTER OWNER SETUP</div><h3 style="margin:14px 0">Contact the organizer</h3><p>{subtitle}</p><form data-draft-form data-form-type="{kind}" method="POST" target="_blank">{frm}<input name="formType" type="hidden" value="{kind}"><div class="flex" style="margin-top:25px;flex-wrap:wrap"><button class="button blue" type="submit">Send enquiry ↗</button><button class="button outline" type="reset">Clear form</button></div><div class="form-message info" role="status"></div></form><p class="small-note" style="margin-top:13px">Email alternative: <a href="mailto:mmmbiharunit@gmail.com">mmmbiharunit@gmail.com</a>. Online form delivery requires the Google Apps Script endpoint to be activated by the organizer.</p></div>'

