 contact=D['contact']; phones=contact['phones']; phonecards=''.join('<a href="tel:'+re.sub(r'[^+0-9]','',p)+'" class="direct-contact"><span>CALL THE ORGANIZING TEAM</span><b>'+p+'</b><small>Tap to call ↗</small></a>' for p in phones)
